//! ▶️ Each admitted scalar instruction preserves the original execution cap separately from physical work and storage.
use super::*;
use semio_framework_actor::{OriginalGuestExecutionBudget,OriginalGuestExecutionReceipt};
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub enum CoreOriginalInvocationStatus{Pending,Complete,Cancelled,Deadline}
pub struct CoreOriginalInvocationCall{pub result:Result<CoreOriginalInvocationStatus,OriginalTurnFailure>,pub execution:OriginalGuestExecutionReceipt}
impl CoreInstanceOpening{
 pub fn begin_function_step(&mut self,module:&Arc<CoreModule>,function:u32,arguments:&[Value],cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
  self.validate(module,cx)?;if !self.resources_ready(){return Err(refused("Core invocation requires its fully initialized original resources").into())}if self.core.as_ref().unwrap().machine.is_some(){return Err(refused("Core invocation must retire its preceding machine before admission").into())}if cx.is_cancelled()||cx.should_yield(){return Ok(false)}
  let (type_index,locals,body)=match module.functions.get(function as usize){Some(FunctionDecl::Defined{type_index,locals,body,..})=>(*type_index,locals,body),_=>return Err(refused("Core opening requires an owned defined function").into())};let signature=module.types.get(type_index as usize).ok_or_else(||refused("Core opening function type is absent"))?;if arguments.len()!=signature.parameters.len()||arguments.iter().zip(&signature.parameters).any(|(value,ty)|value.value_type()!=*ty){return Err(refused("Core opening arguments differ from their original function type").into())}let local_count=arguments.len().checked_add(locals.len()).ok_or_else(||refused("Core opening local count overflow"))?;let results=bytes_for::<ValueType>(signature.results.len())?;let local_bytes=bytes_for::<Value>(local_count)?;let capacity=size_of::<Frame>().checked_add(size_of::<ControlFrame>()).and_then(|n|n.checked_add(local_bytes)).and_then(|n|n.checked_add(results.checked_mul(2)?)).ok_or_else(||refused("Core machine storage size overflow"))?;let copy=capacity.checked_add(size_of::<Machine>()).ok_or_else(||refused("Core machine copy size overflow"))?;let end_pc=body.len().checked_sub(1).ok_or_else(||refused("Core function has no terminating instruction"))?;if !charge(cx,copy,capacity,0)?{return Ok(false)}
  let mut local_values=Vec::with_capacity(local_count);local_values.extend_from_slice(arguments);local_values.extend(locals.iter().copied().map(ValueType::zero));let mut branch_types=Vec::with_capacity(signature.results.len());branch_types.extend_from_slice(&signature.results);let mut result_types=Vec::with_capacity(signature.results.len());result_types.extend_from_slice(&signature.results);let mut controls=Vec::with_capacity(1);controls.push(ControlFrame{kind:ControlKind::Function,start_pc:0,end_pc,stack_height:0,branch_types,result_types});let mut frames=Vec::with_capacity(1);frames.push(Frame{function,pc:0,locals:local_values,stack_base:0,controls});self.core.as_mut().unwrap().machine=Some(Machine{values:Vec::new(),frames,pending_host:None});self.invocation_complete=false;self.returning_frame=false;Ok(true)
 }
 pub fn invocation_values(&self)->Option<&[Value]>{self.invocation_complete.then(||self.core.as_ref()?.machine.as_ref().map(|machine|machine.values.as_slice())).flatten()}
 pub fn advance_scalar(&mut self,module:&Arc<CoreModule>,execution:OriginalGuestExecutionBudget,cx:&mut StepContext<'_>)->Result<CoreOriginalInvocationCall,OriginalTurnFailure>{
  self.validate(module,cx)?;let input=execution.input;if input.operation!=cx.operation().0||input.generation!=cx.generation().0||Some(input.epoch)!=cx.original_source_epoch()||input.grant!=cx.retained_grant(){return Err(refused("Core execution requires the actual incoming input and unchanged physical ceiling").into())}execution.validate_original(input,cx.deadline_us())?;let mut used=0;
  let result=(||{if self.invocation_complete{return Ok(CoreOriginalInvocationStatus::Complete)}while used<execution.fuel{if cx.is_cancelled(){return Ok(CoreOriginalInvocationStatus::Cancelled)}if cx.deadline_exceeded(){return Ok(CoreOriginalInvocationStatus::Deadline)}if cx.should_yield(){return Ok(CoreOriginalInvocationStatus::Pending)}let core=self.core.as_mut().unwrap();let machine=core.machine.as_mut().ok_or_else(||refused("Core scalar execution has no admitted machine"))?;if self.returning_frame{if close_returned_frame(machine,cx)?{self.returning_frame=false;}return Ok(CoreOriginalInvocationStatus::Pending)}let frame=machine.frames.last().ok_or_else(||refused("Core scalar execution has no retained frame"))?;let body=match module.functions.get(frame.function as usize){Some(FunctionDecl::Defined{body,..})=>body,_=>return Err(refused("Core scalar execution has no original body").into())};let mut pc=frame.pc;let opcode=*body.get(pc).ok_or_else(||refused("Core scalar instruction exceeds its original body"))?;pc+=1;
   let action=match opcode{0x01=>Action::Nop,0x0b|0x0f=>{if machine.values.len().checked_sub(frame.stack_base)!=Some(frame.controls[0].result_types.len())||machine.values[frame.stack_base..].iter().zip(&frame.controls[0].result_types).any(|(value,ty)|value.value_type()!=*ty){return Err(refused("Core scalar return differs from its original result type").into())}Action::Complete},0x10=>{let function=unsigned(body,&mut pc)?;Action::Call(u32::try_from(function).map_err(|_|refused("Core original call function exceeds its declared width"))?)},0x1a=>{if machine.values.is_empty(){return Err(refused("Core scalar drop requires its original operand").into())}Action::Drop},0x20=>{let index=unsigned(body,&mut pc)?;Action::Push(*frame.locals.get(index).ok_or_else(||refused("Core scalar local is absent"))?)},0x21|0x22=>{let index=unsigned(body,&mut pc)?;let target=frame.locals.get(index).ok_or_else(||refused("Core scalar local is absent"))?;let value=*machine.values.last().ok_or_else(||refused("Core scalar local assignment has no original operand"))?;if target.value_type()!=value.value_type(){return Err(refused("Core scalar local assignment changes its type").into())}Action::Local(index,value,opcode==0x21)},0x23=>{let index=unsigned(body,&mut pc)?;Action::Push(core.globals.get(index).ok_or_else(||refused("Core scalar global is absent"))?.value)},0x24=>{let index=unsigned(body,&mut pc)?;let target=core.globals.get(index).ok_or_else(||refused("Core scalar global is absent"))?;let value=*machine.values.last().ok_or_else(||refused("Core scalar global assignment has no original operand"))?;if !target.mutable||target.value.value_type()!=value.value_type(){return Err(refused("Core scalar global assignment changes immutable original storage").into())}Action::Global(index,value)},0x28..=0x3e=>{let alignment=unsigned(body,&mut pc)?;if alignment>=64{return Err(refused("Core original memory plan requires its declared default memory").into())}let offset=unsigned64(body,&mut pc)?;let memory=core.memories.first().ok_or_else(||refused("Core original memory instruction has no retained memory"))?;let(address,width)=plan_memory_address(memory,machine,opcode,offset)?;Action::Memory(opcode,address,width)},0x41=>Action::Push(Value::I32(signed(body,&mut pc,32)?as i32)),0x42=>Action::Push(Value::I64(signed(body,&mut pc,64)?)),0x43=>Action::Push(Value::F32(u32::from_le_bytes(fixed::<4>(body,&mut pc)?))),0x44=>Action::Push(Value::F64(u64::from_le_bytes(fixed::<8>(body,&mut pc)?))),0x6a|0x6b|0x6c=>{let (a,b)=last_two(machine)?;let(a,b)=match(a,b){(Value::I32(a),Value::I32(b))=>(a,b),_=>return Err(refused("Core scalar arithmetic requires original i32 operands").into())};Action::Binary(Value::I32(match opcode{0x6a=>a.wrapping_add(b),0x6b=>a.wrapping_sub(b),_=>a.wrapping_mul(b)}))},0x7c|0x7d|0x7e=>{let (a,b)=last_two(machine)?;let(a,b)=match(a,b){(Value::I64(a),Value::I64(b))=>(a,b),_=>return Err(refused("Core scalar arithmetic requires original i64 operands").into())};Action::Binary(Value::I64(match opcode{0x7c=>a.wrapping_add(b),0x7d=>a.wrapping_sub(b),_=>a.wrapping_mul(b)}))},_=>return Err(refused("Core instruction has no admitted original physical execution plan").into())};
   if let Action::Memory(opcode,address,width)=action{if !admit_memory_instruction(&mut core.memories[0],machine,opcode,address,width,cx)?{return Ok(CoreOriginalInvocationStatus::Pending)}used+=1;machine.frames.last_mut().unwrap().pc=pc;continue}if let Action::Call(function)=action{if !admit_defined_frame(module,function,machine,cx)?{return Ok(CoreOriginalInvocationStatus::Pending)}used+=1;let caller=machine.frames.len()-2;machine.frames[caller].pc=pc;continue}if matches!(action,Action::Push(_))&&machine.values.len()==machine.values.capacity(){if !grow_values(&mut machine.values,cx)?{return Ok(CoreOriginalInvocationStatus::Pending)}}if !charge(cx,size_of::<Value>()+size_of::<usize>()+usize::from(matches!(action,Action::Complete)&&machine.frames.len()>1),0,0)?{return Ok(CoreOriginalInvocationStatus::Pending)}used+=1;match action{Action::Nop=>{},Action::Complete=>{machine.frames.last_mut().unwrap().pc=pc;if machine.frames.len()>1{self.returning_frame=true;return Ok(CoreOriginalInvocationStatus::Pending)}self.invocation_complete=true;return Ok(CoreOriginalInvocationStatus::Complete)},Action::Drop=>{machine.values.pop();},Action::Push(value)=>machine.values.push(value),Action::Local(index,value,pop)=>{machine.frames.last_mut().unwrap().locals[index]=value;if pop{machine.values.pop();}},Action::Global(index,value)=>{core.globals[index].value=value;machine.values.pop();},Action::Binary(value)=>{machine.values.pop();*machine.values.last_mut().unwrap()=value;},Action::Call(_)|Action::Memory(_,_,_)=>unreachable!()}machine.frames.last_mut().unwrap().pc=pc;
  }Ok(CoreOriginalInvocationStatus::Pending)})();Ok(CoreOriginalInvocationCall{result,execution:OriginalGuestExecutionReceipt{budget:execution,spent_fuel:Some(used),submitted:true}})
 }
 pub fn close_invocation_step(&mut self,module:&Arc<CoreModule>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
  self.validate(module,cx)?;let Some(machine)=self.core.as_mut().unwrap().machine.as_mut()else{return Ok(true)};if machine.pending_host.is_some(){return Err(refused("Core scalar machine cannot discard a live original host call").into())}if let Some(frame)=machine.frames.last_mut(){if let Some(control)=frame.controls.last_mut(){if release_vector(&mut control.branch_types,cx)?||release_vector(&mut control.result_types,cx)?{return Ok(false)}if charge(cx,size_of::<ControlFrame>(),0,0)?{frame.controls.pop();}return Ok(false)}if release_vector(&mut frame.controls,cx)?||release_vector(&mut frame.locals,cx)?{return Ok(false)}if charge(cx,size_of::<Frame>(),0,0)?{machine.frames.pop();}return Ok(false)}if release_vector(&mut machine.frames,cx)?||release_vector(&mut machine.values,cx)?{return Ok(false)}if !charge(cx,size_of::<Machine>()+size_of::<bool>(),0,0)?{return Ok(false)}self.core.as_mut().unwrap().machine.take();self.invocation_complete=false;Ok(true)
 }
}
enum Action{Nop,Complete,Call(u32),Memory(u8,usize,usize),Drop,Push(Value),Local(usize,Value,bool),Global(usize,Value),Binary(Value)}
fn last_two(machine:&Machine)->Result<(Value,Value),ValueError>{let count=machine.values.len();if count<2{return Err(refused("Core scalar arithmetic requires two original operands"))}Ok((machine.values[count-2],machine.values[count-1]))}
fn unsigned(body:&[u8],pc:&mut usize)->Result<usize,ValueError>{let mut value=0usize;for shift in (0..35).step_by(7){let byte=*body.get(*pc).ok_or_else(||refused("Core unsigned operand exceeds original bytecode"))?;*pc+=1;value|=usize::from(byte&127).checked_shl(shift).ok_or_else(||refused("Core unsigned operand exceeds original host width"))?;if byte&128==0{return Ok(value)}}Err(refused("Core unsigned operand exceeds its original integer width"))}
fn signed(body:&[u8],pc:&mut usize,width:u32)->Result<i64,ValueError>{let mut value=0u64;let mut shift=0;loop{let byte=*body.get(*pc).ok_or_else(||refused("Core signed operand exceeds original bytecode"))?;*pc+=1;value|=u64::from(byte&127).checked_shl(shift).ok_or_else(||refused("Core signed operand exceeds original integer width"))?;shift+=7;if byte&128==0{if shift<64&&byte&64!=0{value|=u64::MAX<<shift}return Ok(value as i64)}if shift>=width+7{return Err(refused("Core signed operand exceeds original integer width"))}}}
fn fixed<const N:usize>(body:&[u8],pc:&mut usize)->Result<[u8;N],ValueError>{let end=pc.checked_add(N).ok_or_else(||refused("Core fixed operand position overflow"))?;let bytes=body.get(*pc..end).and_then(|bytes|bytes.try_into().ok()).ok_or_else(||refused("Core fixed operand exceeds original bytecode"))?;*pc=end;Ok(bytes)}
fn grow_values(values:&mut Vec<Value>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let capacity=values.len().checked_add(1).ok_or_else(||refused("Core operand storage count overflow"))?;let birth=bytes_for::<Value>(capacity)?;let release=bytes_for::<Value>(values.capacity())?;let copy=bytes_for::<Value>(values.len())?;if !charge(cx,copy,birth,release)?{return Ok(false)}let mut replacement=Vec::with_capacity(capacity);replacement.extend(values.drain(..));*values=replacement;Ok(true)}

fn admit_defined_frame(module:&CoreModule,function:u32,machine:&mut Machine,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
 let(type_index,locals,body)=match module.functions.get(function as usize){Some(FunctionDecl::Defined{type_index,locals,body,..})=>(*type_index,locals,body),_=>return Err(refused("Core original call requires a planned defined callee").into())};let signature=module.types.get(type_index as usize).ok_or_else(||refused("Core original call type is absent"))?;let start=machine.values.len().checked_sub(signature.parameters.len()).ok_or_else(||refused("Core original call has fewer operands than its declared parameters"))?;if machine.values[start..].iter().zip(&signature.parameters).any(|(value,ty)|value.value_type()!=*ty){return Err(refused("Core original call parameters differ from their actual types").into())}let count=signature.parameters.len().checked_add(locals.len()).ok_or_else(||refused("Core original callee local count overflow"))?;let local_bytes=bytes_for::<Value>(count)?;let type_bytes=bytes_for::<ValueType>(signature.results.len())?;let frame_bytes=local_bytes.checked_add(type_bytes.checked_mul(2).ok_or_else(||refused("Core original call type size overflow"))?).and_then(|bytes|bytes.checked_add(size_of::<ControlFrame>())).ok_or_else(||refused("Core original call storage size overflow"))?;let grow=machine.frames.len()==machine.frames.capacity();let capacity=machine.frames.len().checked_add(1).ok_or_else(||refused("Core original frame count overflow"))?;let vector_birth=if grow{bytes_for::<Frame>(capacity)?}else{0};let release=if grow{bytes_for::<Frame>(machine.frames.capacity())?}else{0};let relocation=if grow{bytes_for::<Frame>(machine.frames.len())?}else{0};let birth=frame_bytes.checked_add(vector_birth).ok_or_else(||refused("Core original call birth size overflow"))?;let copy=frame_bytes.checked_add(relocation).and_then(|bytes|bytes.checked_add(size_of::<Frame>()+size_of::<Value>()+2*size_of::<usize>())).ok_or_else(||refused("Core original call copy size overflow"))?;let end_pc=body.len().checked_sub(1).ok_or_else(||refused("Core original callee has no terminating instruction"))?;if !charge(cx,copy,birth,release)?{return Ok(false)}
 let mut local_values=Vec::with_capacity(count);local_values.extend_from_slice(&machine.values[start..]);local_values.extend(locals.iter().copied().map(ValueType::zero));let mut branch_types=Vec::with_capacity(signature.results.len());branch_types.extend_from_slice(&signature.results);let mut result_types=Vec::with_capacity(signature.results.len());result_types.extend_from_slice(&signature.results);let mut controls=Vec::with_capacity(1);controls.push(ControlFrame{kind:ControlKind::Function,start_pc:0,end_pc,stack_height:start,branch_types,result_types});let frame=Frame{function,pc:0,locals:local_values,stack_base:start,controls};if grow{let mut replacement=Vec::with_capacity(capacity);replacement.extend(machine.frames.drain(..));machine.frames=replacement;}machine.values.truncate(start);machine.frames.push(frame);Ok(true)
}
fn close_returned_frame(machine:&mut Machine,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
 if machine.frames.len()<2{return Err(refused("Core returned callee must keep its actual parent frame").into())}let frame=machine.frames.last_mut().unwrap();if let Some(control)=frame.controls.last_mut(){if release_vector(&mut control.branch_types,cx)?||release_vector(&mut control.result_types,cx)?{return Ok(false)}if charge(cx,size_of::<ControlFrame>(),0,0)?{frame.controls.pop();}return Ok(false)}if release_vector(&mut frame.controls,cx)?||release_vector(&mut frame.locals,cx)?{return Ok(false)}if !charge(cx,size_of::<Frame>()+size_of::<bool>(),0,0)?{return Ok(false)}machine.frames.pop();Ok(true)
}

fn unsigned64(body:&[u8],pc:&mut usize)->Result<u64,ValueError>{let mut value=0u64;for shift in (0..70).step_by(7){let byte=*body.get(*pc).ok_or_else(||refused("Core original memory offset exceeds its bytecode"))?;*pc+=1;if shift==63&&byte&126!=0{return Err(refused("Core original memory offset exceeds its integer width"))}value|=u64::from(byte&127)<<shift;if byte&128==0{return Ok(value)}}Err(refused("Core original memory offset exceeds its integer width"))}
fn plan_memory_address(memory:&MemoryState,machine:&Machine,opcode:u8,offset:u64)->Result<(usize,usize),ValueError>{
 let store=opcode>=0x36;let index=machine.values.len().checked_sub(if store{2}else{1}).ok_or_else(||refused("Core original memory instruction has no address operand"))?;let base=match(machine.values[index],memory.memory64){(Value::I32(value),false)=>u64::from(value as u32),(Value::I64(value),true)=>value as u64,_=>return Err(refused("Core original memory address differs from its declared width"))};let width=match opcode{0x28|0x2a|0x34|0x35|0x36|0x38|0x3e=>4,0x29|0x2b|0x37|0x39=>8,0x2c|0x2d|0x30|0x31|0x3a|0x3c=>1,_=>2};let address=base.checked_add(offset).and_then(|value|usize::try_from(value).ok()).ok_or_else(||refused("Core original memory address exceeds its host width"))?;address.checked_add(width).filter(|end|*end<=memory.bytes.len()).ok_or_else(||refused("Core original memory instruction exceeds its retained extent"))?;if store{let expected=match opcode{0x36|0x3a|0x3b=>ValueType::I32,0x38=>ValueType::F32,0x39=>ValueType::F64,_=>ValueType::I64};if machine.values.last().unwrap().value_type()!=expected{return Err(refused("Core original stored scalar differs from its declared type"))}}Ok((address,width))
}
fn admit_memory_instruction(memory:&mut MemoryState,machine:&mut Machine,opcode:u8,address:usize,width:usize,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
 let store=opcode>=0x36;let copy=width+size_of::<Value>()*if store{2}else{1}+size_of::<usize>();if !charge(cx,copy,0,0)?{return Ok(false)}if store{let value=*machine.values.last().unwrap();let bytes=match value{Value::I32(value)=>(value as u32 as u64).to_le_bytes(),Value::I64(value)=>(value as u64).to_le_bytes(),Value::F32(bits)=>u64::from(bits).to_le_bytes(),Value::F64(bits)=>bits.to_le_bytes(),_=>unreachable!()};memory.bytes[address..address+width].copy_from_slice(&bytes[..width]);machine.values.pop();machine.values.pop();}else{let mut bytes=[0u8;8];bytes[..width].copy_from_slice(&memory.bytes[address..address+width]);let value=u64::from_le_bytes(bytes);let scalar=match opcode{0x28=>Value::I32(value as u32 as i32),0x29=>Value::I64(value as i64),0x2a=>Value::F32(value as u32),0x2b=>Value::F64(value),0x2c=>Value::I32(value as u8 as i8 as i32),0x2d=>Value::I32(value as u8 as i32),0x2e=>Value::I32(value as u16 as i16 as i32),0x2f=>Value::I32(value as u16 as i32),0x30=>Value::I64(value as u8 as i8 as i64),0x31=>Value::I64(value as u8 as i64),0x32=>Value::I64(value as u16 as i16 as i64),0x33=>Value::I64(value as u16 as i64),0x34=>Value::I64(value as u32 as i32 as i64),0x35=>Value::I64(value as u32 as i64),_=>unreachable!()};*machine.values.last_mut().unwrap()=scalar;}Ok(true)
}
